package dev.giona.ktconf.ai

import dev.giona.ktconf.domain.ConfidentialDocument
import dev.giona.ktconf.domain.DocumentAnalysis
import dev.tramai.core.annotations.AiService
import dev.tramai.core.annotations.Operation
import dev.tramai.core.model.ClassifiedDocument

@AiService
interface DocumentAnalysisAi {

    companion object {
        const val DLP_ANALYSIS_PROMPT: String =
            "Analyze the trusted confidential document and return a structured DocumentAnalysis. " +
                "Copy documentId, company, amount, contactEmail, and paymentIban exactly as they " +
                "appear in the document. summary must be a concise sentence describing the payment " +
                "purpose. Do not omit the contactEmail or paymentIban fields."
    }

    @Operation(
        prompt = DLP_ANALYSIS_PROMPT,
        model = "eu-scaleway-invoice-model",
        timeoutMillis = InvoiceAnalysisService.MODEL_ATTEMPT_TIMEOUT_MILLIS,
    )
    suspend fun analyzeDocument(
        document: ClassifiedDocument<ConfidentialDocument>,
    ): DocumentAnalysis
}

package dev.giona.ktconf.api

import dev.giona.ktconf.application.DlpDemoResult
import dev.giona.ktconf.application.DlpDemoService
import org.springframework.http.ResponseEntity
import org.springframework.web.bind.annotation.PostMapping
import org.springframework.web.bind.annotation.RequestMapping
import org.springframework.web.bind.annotation.RequestPart
import org.springframework.web.bind.annotation.RestController
import org.springframework.web.multipart.MultipartFile

@RestController
@RequestMapping("/documents/dlp")
class DlpDemoController(
    private val service: DlpDemoService,
) {
    @PostMapping("/analyze", consumes = ["multipart/form-data"])
    suspend fun analyze(
        @RequestPart("file") file: MultipartFile,
    ): ResponseEntity<DlpDemoResult> = ResponseEntity.ok(service.analyze(file))
}

package dev.giona.ktconf.application

import dev.giona.ktconf.ai.DocumentAnalysisAi
import dev.giona.ktconf.domain.ConfidentialDocument
import dev.giona.ktconf.domain.DocumentAnalysis
import dev.giona.ktconf.domain.toClassifiedDocument
import dev.giona.ktconf.observability.DlpRedactionEvidenceStore
import dev.giona.ktconf.observability.DlpRedactionSummary
import dev.giona.ktconf.pdf.DlpDemoPdfIngestionService
import dev.giona.ktconf.pdf.DlpTrustedDocument
import dev.giona.ktconf.pdf.TrustedPdfMetadata
import dev.tramai.core.policy.ClassificationSource
import io.opentelemetry.api.OpenTelemetry
import io.opentelemetry.api.trace.StatusCode
import org.slf4j.LoggerFactory
import org.springframework.stereotype.Service
import org.springframework.web.multipart.MultipartFile

@Service
class DlpDemoService(
    private val pdfIngestion: DlpDemoPdfIngestionService,
    private val ai: DocumentAnalysisAi,
    private val dlpEvidence: DlpRedactionEvidenceStore,
    openTelemetry: OpenTelemetry,
) {
    private val tracer = openTelemetry.getTracer("dev.giona.ktconf.dlp")
    private val log = LoggerFactory.getLogger(javaClass)

    suspend fun analyze(file: MultipartFile): DlpDemoResult {
        val span = tracer.spanBuilder("document.dlp.analyze").startSpan()
        val scope = span.makeCurrent()
        return try {
            val trusted = traceIngest(file)
            span.setAttribute("document.id", trusted.document.documentId)
            span.setAttribute("document.classification", trusted.metadata.classification.name)
            span.setAttribute("document.residency", trusted.metadata.residency.name)
            span.setAttribute("tramai.route", InvoiceRoute.EU_CLOUD.name)
            span.setAttribute("tramai.operation", "analyzeDocument")
            log.info(
                "DLP demo document accepted: documentId={}, classification={}",
                trusted.document.documentId,
                trusted.metadata.classification,
            )

            val checkpoint = dlpEvidence.checkpoint()
            val analysis = ai.analyzeDocument(
                trusted.document.toClassifiedDocument(ClassificationSource.RULE_BASED),
            )
            log.info("AI operation completed: documentId={}", trusted.document.documentId)

            val summary = dlpEvidence.summarySince(checkpoint, "analyzeDocument")
            validateBoundary(analysis, summary)
            span.setAttribute("dlp.redacted", true)
            span.setAttribute("dlp.replacement_count", summary.replacementCount.toLong())
            span.setStatus(StatusCode.OK)

            DlpDemoResult(
                document = trusted.document.safeView(),
                metadata = trusted.metadata,
                selectedRoute = InvoiceRoute.EU_CLOUD,
                classificationSource = ClassificationSource.RULE_BASED,
                operation = "analyzeDocument",
                analysis = analysis,
                dlp = summary.toView(),
            )
        } catch (error: Throwable) {
            span.recordException(error)
            span.setStatus(StatusCode.ERROR, error.message ?: "DLP demo failed")
            throw error
        } finally {
            scope.close()
            span.end()
        }
    }

    private fun traceIngest(file: MultipartFile): DlpTrustedDocument {
        val span = tracer.spanBuilder("document.ingest").startSpan()
        val scope = span.makeCurrent()
        return try {
            pdfIngestion.readTrustedDocument(file).also { trusted ->
                span.setAttribute("document.id", trusted.document.documentId)
                span.setAttribute("document.classification", trusted.metadata.classification.name)
                span.setAttribute("document.residency", trusted.metadata.residency.name)
                span.setAttribute("document.contains_email", true)
                span.setAttribute("document.contains_iban", true)
                span.setStatus(StatusCode.OK)
            }
        } catch (error: Throwable) {
            span.recordException(error)
            span.setStatus(StatusCode.ERROR, error.message ?: "Document ingest failed")
            throw error
        } finally {
            scope.close()
            span.end()
        }
    }

    private fun validateBoundary(
        analysis: DocumentAnalysis,
        summary: DlpRedactionSummary,
    ) {
        require(analysis.contactEmail == "[EMAIL_REDACTED]") {
            "DLP demo expected contactEmail to be redacted by TramAI"
        }
        require(analysis.paymentIban == "[IBAN_REDACTED]") {
            "DLP demo expected paymentIban to be redacted by TramAI"
        }
        val rules = summary.appliedRules.associate { it.ruleId to it.replacementCount }
        require(rules == mapOf("email" to 1, "iban" to 1)) {
            "DLP demo expected one email and one iban redaction"
        }
        require(summary.replacementCount == 2) {
            "DLP demo expected exactly two redactions"
        }
    }
}

data class DlpDemoResult(
    val document: DlpDocumentView,
    val metadata: TrustedPdfMetadata,
    val selectedRoute: InvoiceRoute,
    val classificationSource: ClassificationSource,
    val operation: String,
    val analysis: DocumentAnalysis,
    val dlp: DlpView,
)

data class DlpDocumentView(
    val documentId: String,
    val company: String,
    val amount: String,
    val purpose: String,
    val sensitiveSignals: List<String>,
)

data class DlpView(
    val redacted: Boolean,
    val replacementCount: Int,
    val ruleIds: List<String>,
    val audit: List<DlpAuditView>,
)

data class DlpAuditView(
    val decision: String,
    val ruleId: String,
    val replacementCount: Int,
)

private fun ConfidentialDocument.safeView(): DlpDocumentView = DlpDocumentView(
    documentId = documentId,
    company = company,
    amount = amount,
    purpose = purpose,
    sensitiveSignals = listOf("EMAIL DETECTED", "IBAN DETECTED"),
)

private fun DlpRedactionSummary.toView(): DlpView = DlpView(
    redacted = true,
    replacementCount = replacementCount,
    ruleIds = appliedRules.map { it.ruleId },
    audit = appliedRules.map { rule ->
        DlpAuditView(
            decision = "REDACTED",
            ruleId = rule.ruleId,
            replacementCount = rule.replacementCount,
        )
    },
)

package dev.giona.ktconf.pdf

import dev.giona.ktconf.domain.ConfidentialDocument
import dev.tramai.core.policy.DataClassification
import java.io.IOException
import org.apache.pdfbox.Loader
import org.apache.pdfbox.text.PDFTextStripper
import org.springframework.stereotype.Service
import org.springframework.web.multipart.MultipartFile

data class DlpTrustedDocument(
    val document: ConfidentialDocument,
    val metadata: TrustedPdfMetadata,
)

@Service
class DlpDemoPdfIngestionService(
    private val trustedPdfIngestionService: TrustedPdfIngestionService,
) {

    fun readTrustedDocument(file: MultipartFile): DlpTrustedDocument {
        val trusted = trustedPdfIngestionService.readTrustedMetadata(file)
        if (trusted.metadata.classification != DataClassification.CONFIDENTIAL) {
            throw InvalidTrustedPdfException("DLP demo requires trusted CONFIDENTIAL classification")
        }
        if (trusted.metadata.residency != DataResidency.EU_ONLY) {
            throw InvalidTrustedPdfException("DLP demo requires trusted EU_ONLY residency")
        }

        try {
            Loader.loadPDF(trusted.bytes).use { document ->
                val text = PDFTextStripper().getText(document)
                return DlpTrustedDocument(
                    document = parseDocument(text),
                    metadata = trusted.metadata,
                )
            }
        } catch (error: IOException) {
            throw InvalidTrustedPdfException("Malformed or unsupported PDF", error)
        }
    }

    private fun parseDocument(text: String): ConfidentialDocument {
        val lines = text.lineSequence()
            .map(String::trim)
            .toList()

        fun lineValue(prefix: String): String = lines.firstOrNull { it.startsWith(prefix) }
            ?.substringAfter(prefix)
            ?.trim()
            ?.takeIf { it.isNotEmpty() }
            ?: throw InvalidTrustedPdfException("DLP document field is missing: $prefix")

        fun blockValue(heading: String): String {
            val start = lines.indexOfFirst { it == heading }
            if (start == -1) {
                throw InvalidTrustedPdfException("DLP document field is missing: $heading")
            }
            return lines.drop(start + 1)
                .firstOrNull { it.isNotBlank() }
                ?.trim()
                ?.takeIf { it.isNotEmpty() }
                ?: throw InvalidTrustedPdfException("DLP document field is missing: $heading")
        }

        val document = ConfidentialDocument(
            documentId = lineValue("DOCUMENT ID:"),
            company = lineValue("Company:"),
            amount = lineValue("Amount:"),
            purpose = lineValue("Purpose:"),
            paymentIban = blockValue("Payment IBAN:"),
            contactEmail = blockValue("Contact:"),
            notes = blockValue("Notes:"),
        )
        if (document.documentId != "KTCONF-DLP-001") {
            throw InvalidTrustedPdfException("Unsupported DLP demo document: ${document.documentId}")
        }
        return document
    }
}

package dev.giona.ktconf.observability

import dev.tramai.core.security.DlpContentType
import dev.tramai.core.security.DlpContext
import dev.tramai.core.security.DlpRedaction
import java.time.Instant
import java.util.concurrent.CopyOnWriteArrayList
import java.util.concurrent.atomic.AtomicLong
import org.springframework.stereotype.Component

@Component
class DlpRedactionEvidenceStore {
    private val sequence = AtomicLong(0)
    private val records = CopyOnWriteArrayList<DlpRedactionRecord>()

    fun checkpoint(): Long = sequence.get()

    fun record(
        context: DlpContext,
        redactions: List<DlpRedaction>,
    ) {
        redactions.forEach { redaction ->
            records += DlpRedactionRecord(
                sequence = sequence.incrementAndGet(),
                recordedAt = Instant.now(),
                context = context,
                ruleId = redaction.ruleId,
                replacementCount = redaction.replacementCount,
            )
        }
    }

    fun summarySince(
        checkpoint: Long,
        operationMethod: String,
    ): DlpRedactionSummary {
        val matching = records
            .filter {
                it.sequence > checkpoint &&
                    it.context.contentType == DlpContentType.MODEL_OUTPUT &&
                    it.context.operationMethod == operationMethod
            }
            .sortedBy { it.sequence }
        require(matching.isNotEmpty()) {
            "No DLP redaction evidence was recorded for $operationMethod"
        }

        val first = matching.first()
        val correlationId = first.context.correlationId
        val grouped = matching
            .filter { it.context.correlationId == correlationId }
            .groupBy { it.ruleId }
            .toSortedMap()
            .map { (ruleId, entries) ->
                DlpAppliedRule(
                    ruleId = ruleId,
                    replacementCount = entries.sumOf { it.replacementCount },
                )
            }

        return DlpRedactionSummary(
            correlationId = correlationId,
            operationInterface = first.context.operationInterface,
            operationMethod = first.context.operationMethod,
            providerId = first.context.providerId,
            modelName = first.context.modelName,
            replacementCount = grouped.sumOf { it.replacementCount },
            appliedRules = grouped,
        )
    }

    fun latestSummary(
        operationMethod: String,
    ): DlpRedactionSummary? {
        val checkpoint = (records.maxOfOrNull { it.sequence } ?: return null) - 100
        return runCatching { summarySince(checkpoint, operationMethod) }.getOrNull()
    }
}

data class DlpRedactionRecord(
    val sequence: Long,
    val recordedAt: Instant,
    val context: DlpContext,
    val ruleId: String,
    val replacementCount: Int,
)

data class DlpRedactionSummary(
    val correlationId: String,
    val operationInterface: String,
    val operationMethod: String,
    val providerId: String?,
    val modelName: String?,
    val replacementCount: Int,
    val appliedRules: List<DlpAppliedRule>,
)

data class DlpAppliedRule(
    val ruleId: String,
    val replacementCount: Int,
)

package dev.giona.ktconf.observability

import dev.tramai.core.security.DlpContext
import dev.tramai.core.security.DlpInterceptor
import dev.tramai.core.security.DlpRedaction
import dev.tramai.core.security.DlpRedactionAuditEmitter
import dev.tramai.security.DlpRule
import dev.tramai.security.RuleBasedDlpConfiguration
import dev.tramai.security.RuleBasedDlpInterceptor
import dev.tramai.security.audit.AuditEngine
import dev.tramai.security.audit.AuditEngineDlpRedactionAuditEmitter
import dev.tramai.security.audit.AuditStore
import io.opentelemetry.api.OpenTelemetry
import io.opentelemetry.api.common.Attributes
import io.opentelemetry.api.trace.StatusCode
import org.slf4j.LoggerFactory
import org.springframework.context.annotation.Bean
import org.springframework.context.annotation.Configuration

@Configuration(proxyBeanMethods = false)
class DlpRuntimeConfiguration {

    @Bean
    fun dlpInterceptor(): DlpInterceptor = RuleBasedDlpInterceptor(
        RuleBasedDlpConfiguration(
            rules = listOf(
                DlpRule(
                    id = "email",
                    pattern = "[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}",
                    replacement = "[EMAIL_REDACTED]",
                ),
                DlpRule(
                    id = "iban",
                    pattern = "\\b[A-Z]{2}\\d{2}[A-Z0-9]{4}\\d{10}\\b",
                    replacement = "[IBAN_REDACTED]",
                ),
            ),
        ),
    )

    @Bean
    fun dlpRedactionAuditEmitter(
        auditStore: AuditStore,
        openTelemetry: OpenTelemetry,
        evidenceStore: DlpRedactionEvidenceStore,
    ): DlpRedactionAuditEmitter = SafeDlpRedactionAuditEmitter(
        delegate = AuditEngineDlpRedactionAuditEmitter(AuditEngine(auditStore)),
        openTelemetry = openTelemetry,
        evidenceStore = evidenceStore,
    )
}

private class SafeDlpRedactionAuditEmitter(
    private val delegate: DlpRedactionAuditEmitter,
    openTelemetry: OpenTelemetry,
    private val evidenceStore: DlpRedactionEvidenceStore,
) : DlpRedactionAuditEmitter {
    private val tracer = openTelemetry.getTracer("dev.giona.ktconf.dlp")
    private val log = LoggerFactory.getLogger(javaClass)

    override suspend fun emit(
        context: DlpContext,
        redactions: List<DlpRedaction>,
    ) {
        val span = tracer.spanBuilder("dlp.redaction").startSpan()
        val scope = span.makeCurrent()
        try {
            delegate.emit(context, redactions)
            evidenceStore.record(context, redactions)

            span.setAllAttributes(
                Attributes.builder()
                    .put("dlp.redacted", true)
                    .put("dlp.rule_count", redactions.size.toLong())
                    .put("dlp.replacement_count", redactions.sumOf { it.replacementCount }.toLong())
                    .put("dlp.content_type", context.contentType.name)
                    .put("tramai.operation.interface", context.operationInterface)
                    .put("tramai.operation.method", context.operationMethod)
                    .put("tramai.provider", context.providerId ?: "unknown")
                    .put("tramai.model", context.modelName ?: "unknown")
                    .put("document.classification", context.dataClassification?.name ?: "UNKNOWN")
                    .build(),
            )

            redactions.forEach { redaction ->
                span.addEvent(
                    "dlp.redaction.applied",
                    Attributes.builder()
                        .put("dlp.rule_id", redaction.ruleId)
                        .put("dlp.replacement_count", redaction.replacementCount.toLong())
                        .build(),
                )
                log.info(
                    "DLP redaction applied: operation={}, rule={}, replacementCount={}",
                    context.operationMethod,
                    redaction.ruleId,
                    redaction.replacementCount,
                )
            }
            span.setStatus(StatusCode.OK)
        } catch (error: Throwable) {
            span.recordException(error)
            span.setStatus(StatusCode.ERROR, error.message ?: "DLP audit emission failed")
            throw error
        } finally {
            scope.close()
            span.end()
        }
    }
}

package dev.giona.ktconf

import dev.giona.ktconf.demo.DeterministicProvider
import dev.giona.ktconf.demo.cloudScript
import dev.tramai.core.model.Message
import dev.tramai.core.model.ModelRequest
import kotlinx.coroutines.runBlocking
import kotlin.test.Test
import kotlin.test.assertTrue

class DlpDeterministicProviderTest {

    @Test
    fun `deterministic DLP fixture returns raw sensitive values before TramAI DLP`() = runBlocking {
        val provider = DeterministicProvider("eu-scaleway-provider", ::cloudScript)

        val response = provider.complete(
            ModelRequest(
                model = "eu-scaleway-invoice-model",
                messages = listOf(Message.text("""{"documentId":"KTCONF-DLP-001"}""")),
                operationMethod = "analyzeDocument",
            ),
        )

        assertTrue(response.content.contains("finance@example-confidential.eu"))
        assertTrue(response.content.contains("NL91ABNA0417164300"))
    }
}

package dev.giona.ktconf

import dev.giona.ktconf.pdf.DataResidency
import dev.giona.ktconf.pdf.DlpDemoPdfIngestionService
import dev.giona.ktconf.pdf.InvalidTrustedPdfException
import dev.giona.ktconf.pdf.TrustedPdfIngestionService
import org.springframework.mock.web.MockMultipartFile
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertFailsWith

class DlpDemoPdfIngestionServiceTest {
    private val service = DlpDemoPdfIngestionService(TrustedPdfIngestionService())

    @Test
    fun `fixture parses into the expected trusted DLP document`() {
        val parsed = service.readTrustedDocument(fixture())

        assertEquals("KTCONF-DLP-001", parsed.document.documentId)
        assertEquals("Example Conference Services BV", parsed.document.company)
        assertEquals("EUR 4,280.00", parsed.document.amount)
        assertEquals("Conference venue services", parsed.document.purpose)
        assertEquals("finance@example-confidential.eu", parsed.document.contactEmail)
        assertEquals("NL91ABNA0417164300", parsed.document.paymentIban)
        assertEquals("CONFIDENTIAL", parsed.metadata.classification.name)
        assertEquals(DataResidency.EU_ONLY, parsed.metadata.residency)
    }

    @Test
    fun `non DLP repository fixtures fail closed for this endpoint`() {
        val bytes = requireNotNull(
            javaClass.classLoader.getResourceAsStream("fixtures/confidential-eu-invoice.pdf"),
        ).readBytes()

        assertFailsWith<InvalidTrustedPdfException> {
            service.readTrustedDocument(
                MockMultipartFile("file", "confidential-eu-invoice.pdf", "application/pdf", bytes),
            )
        }
    }

    private fun fixture(): MockMultipartFile {
        val bytes = requireNotNull(
            javaClass.classLoader.getResourceAsStream("fixtures/dlp-confidential-document.pdf"),
        ).readBytes()
        return MockMultipartFile("file", "dlp-confidential-document.pdf", "application/pdf", bytes)
    }
}
